// 帧缓冲 + 合并渲染(示意)
let buf = "", pending = "";
stream.on("chunk", (text) => {
  buf += text;
  const frames = buf.split("\n\n");       // 按 SSE 分隔切帧
  buf = frames.pop();                     // 最后一段可能不完整,留缓冲
  pending += frames.map(parseFrame).join("");
});
setInterval(() => {                        // 80ms 合并渲染
  if (pending) { appendToDOM(pending); pending = ""; }
}, 80);
```

